// Checks a run's demos the way the moderators' checker does, plus a few improvements.
//
// The rules follow VolvoWrench's Verification.cs (ParseBxtData). Its literal tables come from
// src/rules.json, generated by tools/rules.ts; the logic below is a port of the rest.
// Improvements: numeric cvar values ("0" equals "0.000000"), a check of the demo set,
// demos without BXT data, broken demos reported instead of stopping, and plain wording.

import { seconds, type Time } from './bxt.ts';
import type { At, Demo } from './demo.ts';
import rules from './rules.json' with { type: 'json' };

/** The fingerprint of VolvoWrench's logic that this file ports (see tools/rules.ts). */
export const PortedLogic = 'b6dfb2805276716e';

export type Mode = 'scriptless' | 'scripted';
export type Severity = 'problem' | 'check' | 'info';
export type Where = { demo: string } & Partial<At>;
export type Finding = { kind: Kind; severity: Severity; subject: string; where: Where[] };
export type Input = { name: string; demo: Demo; hash?: string };

export type Report = {
  mode: Mode;
  detectedMode: Mode;
  /** The demos in run order. */
  demos: { name: string; map: string; time?: Time; error?: string }[];
  /** The BXT timer at the end of the last demo. */
  time?: Time;
  findings: Finding[];
  fps: { highest: number };
  /** Detected from where and how the timer starts; see checkRun. */
  individualLevel: boolean;
  rules: { bxtVersion: string; source: typeof rules.source };
};

export const Kinds = {
  'broken': { severity: 'problem', title: ['A demo is damaged', '# demos are damaged'], fix: 'Copy or download it again.' },
  'unfinished': { severity: 'check', title: ['A demo is unfinished', '# demos are unfinished'], fix: 'The recording stopped early. Its time is only exact to the second, and the moderators have to repair it before their tool opens it.' },
  'missing': { severity: 'problem', title: ['A demo is missing', '# demos are missing'], fix: 'Add the missing demos. BXT numbers them from 1 without gaps.' },
  'conflict': { severity: 'problem', title: ['Two demos share a number', '# demo numbers are used twice'], fix: 'Remove the one that isn\'t from this run.' },
  'copy': { severity: 'check', title: ['A demo is there twice', '# demos are there twice'], fix: 'Remove the copy.' },
  'timer-start': { severity: 'problem', title: ['The timer was already running'], fix: 'Add the earlier demos. If the timer wasn\'t reset at the start, that can\'t be changed now.' },
  'timer-jump': { severity: 'problem', title: ['The timer jumps between demos', 'The timer jumps # times between demos'], fix: 'Add the demo that\'s missing, or put the demos in order.' },
  'load-unseen': { severity: 'problem', title: ['A save wasn\'t made in these demos', '# saves weren\'t made in these demos'], fix: 'It was probably made in a missing demo. Add the missing demos.' },
  'no-game-end': { severity: 'problem', title: ['The game doesn\'t end'], fix: 'The last demo is probably missing. Add it.' },
  'naming': { severity: 'check', title: ['A demo has an unusual name', '# demos have unusual names'], fix: 'BXT names demos like run_1.dem and run_2.dem. Keep those names so the order is clear.' },
  'no-bxt': { severity: 'problem', recorded: true, title: ['A demo has no BXT data', '# demos have no BXT data'], fix: 'Record with BunnymodXT and _bxt_save_runtime_data_in_demos 1 next time.' },
  'bxt-version': { severity: 'problem', recorded: true, title: ['BXT isn\'t the required version'], fix: `Use ${rules.bxtVersion.replace(/^(\w{7})\w*-CLEAN based on (.+)$/, '$1 ($2)')} for your next run.` },
  'cvar': { severity: 'problem', recorded: true, title: ['A setting isn\'t allowed', '# settings aren\'t allowed'], fix: 'Set it to the required value before your next run.' },
  'cvar-format': { severity: 'check', title: ['A setting is written differently', '# settings are written differently'], fix: 'The value is right, but the moderators\' tool will still flag it. Set it exactly as shown to avoid that.' },
  'third-person': { severity: 'check', title: ['A Third Person setting is used', '# Third Person settings are used'], fix: 'It\'s only allowed in Third Person runs.' },
  'physics': { severity: 'check', title: ['A physics setting changed', '# physics settings changed'], fix: 'Physics settings have to stay at their defaults.' },
  'edicts': { severity: 'problem', recorded: true, title: ['The entity limit was raised'], fix: 'Keep edicts at 900 or below next time.' },
  'big-map': { severity: 'problem', recorded: true, title: ['Big map support was left on'], fix: 'Restart the game before your next run.' },
  'bxt-command': { severity: 'problem', recorded: true, title: ['A BXT command isn\'t allowed', '# BXT commands aren\'t allowed'], fix: 'Only use BXT\'s display commands next time.' },
  'disallowed': { severity: 'problem', recorded: true, title: ['A command isn\'t allowed', '# commands aren\'t allowed'], fix: 'Remove it from your configs and binds before your next run.' },
  'probably-disallowed': { severity: 'check', title: ['A command may not be allowed', '# commands may not be allowed'], fix: 'Changing settings mid-run usually isn\'t allowed. A moderator will decide.' },
  'movement-script': { severity: 'problem', recorded: true, title: ['A script presses a movement key', '# scripts press movement keys'], fix: 'Scripts can\'t press movement keys. Press them yourself next time.' },
  'cust': { severity: 'problem', recorded: true, title: ['A cust value is out of range', '# cust values are out of range'], fix: 'Only use cust_11 to cust_45 next time.' },
  'load-unknown': { severity: 'problem', recorded: true, title: ['A save wasn\'t made in this run', '# saves weren\'t made in this run'], fix: 'Only load saves made during the run next time.' },
  'load-named': { severity: 'check', title: ['A named save was loaded', '# named saves were loaded'], fix: 'Saves made during the run are fine. A moderator will take a look.' },
  'report-to-demo': { severity: 'problem', recorded: true, title: ['report_to_demo is bound to a key'], fix: 'Unbind it before your next run. It\'s only for kill counting.' },
  'bind-script': { severity: 'check', title: ['A key runs several commands', '# keys run several commands'], fix: 'Scriptless runs allow one command per key.' },
  'alias-script': { severity: 'check', title: ['An alias runs several commands', '# aliases run several commands'], fix: 'Scriptless runs allow one command per key.' },
  'alias-movement': { severity: 'check', title: ['An alias moves you', '# aliases move you'], fix: 'A moderator will take a look.' },
  'autojump': { severity: 'check', title: ['A jump may be scripted', '# jumps may be scripted'], fix: 'There was no key press for it. Scriptless runs can\'t automate jumps.' },
  'ducktap': { severity: 'check', title: ['A duck may be scripted', '# ducks may be scripted'], fix: 'There was no key press for it. Scriptless runs can\'t automate ducks.' },
  'load': { severity: 'info', title: ['A save was loaded', '# saves were loaded'], fix: '' },
  'config': { severity: 'info', title: ['A config ran', '# configs ran'], fix: '' },
  'game-end': { severity: 'info', title: ['The game ends', 'The game ends # times'], fix: '' },
  'blue-shift': { severity: 'info', title: ['The run is retimed for Blue Shift'], fix: '' },
  'trigger': { severity: 'info', title: ['A custom trigger was set', '# custom triggers were set'], fix: '' },
  'split': { severity: 'info', title: ['A split trigger was set', '# split triggers were set'], fix: '' },
} as const satisfies Record<string, { severity: Severity; recorded?: boolean; title: readonly [string, string?]; fix: string }>;
export type Kind = keyof typeof Kinds;

/** Recorded in the demos, so the run breaks the rules for good. */
export const recorded = (kind: Kind) => 'recorded' in Kinds[kind];

/** A finding's title for `n` items: "A setting isn't allowed", "3 settings aren't allowed". */
export function title(kind: Kind, n: number) {
  const [one, many = one] = Kinds[kind].title as readonly [string, string?];
  return n === 1 ? one : many.replace('#', String(n));
}

// Commands that are always disallowed, unless they start with REPORT_TO_DEMO. WAIT only in Scriptless.
const Disallowed = ['HOST_', 'SK_', 'CHASE', 'SKILL', 'CONNECT', 'DELTA', 'EDGEFRICTION', 'FS_', 'MAPCHANGECFGFILE',
  'NOTARGET', 'PLAYDEMO', 'S_SHOW', 'SPEC_POS', 'THIRDPERSON', 'SCR_', 'CAM', 'JOY'];
const Movement = ['+LEFT', '+RIGHT', '+FORWARD', '+BACK', '+MOVERIGHT', '+MOVELEFT'];
// The command whitelist bans pressing these in scripted sequences, and allows these settings only in Third Person runs.
const ThirdPerson = ['cam_idealyaw', 'thirdperson'];

/** A script with several commands that itself presses a movement key. Pointing a key at one (alias move +moveright) is fine. */
function pressesMovement(script: string) {
  const commands = script.split(';').map(c => c.trim()).filter(Boolean);
  return commands.length > 1 && commands.some(c => Movement.includes(c.split(/\s+/)[0].toUpperCase()));
}
const AlwaysLoadable = ['QUICK', 'HARD', 'AUTOSAVE'];
const BlueShiftStart = 'changelevel2 ba_security1 tram3_security1';
const MaxTimerJump = 2; // Seconds. Complete runs show at most 1.
const StartMap = 'c1a0'; // Where Half-Life full-game runs start.

function disallowed(cmd: string, mode: Mode) {
  return !cmd.startsWith('REPORT_TO_DEMO') &&
    (Disallowed.some(s => cmd.includes(s)) || (mode === 'scriptless' && cmd.includes('WAIT')) || cmd.startsWith('C_'));
}

function probablyDisallowed(cmd: string, mode: Mode) {
  const has = (s: string) => cmd.includes(s);
  return (has('SV_') && !has('AIM')) ||
    (has('CL_') && !(has('BOB') || has('SHOWFPS') || has('RIGHTHAND') || (mode === 'scripted' && (has('PITCHDOWN') || has('PITCHUP'))))) ||
    cmd.startsWith('MP_') || cmd.startsWith('R_') ||
    (has('GL_') && !has('TEXTUREMODE')) ||
    cmd.startsWith('STAT');
}

/** Scripted when the first demo has bxt_autojump 1 or +bxt_tas_autojump (FirstDemoHasAutojump). */
export function detectMode(first: Demo | undefined): Mode {
  for (const g of first?.bxt ?? []) for (const d of g.data) {
    if (d.type === 'cvars' && [...d.values].some(([k, v]) => k.toLowerCase() === 'bxt_autojump' && v.trim() === '1')) return 'scripted';
    if (d.type === 'command' && d.command.trim().toLowerCase().includes('+bxt_tas_autojump')) return 'scripted';
  }
  return 'scriptless';
}

const Numeric = /^\s*[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?\s*$/;

/** VolvoWrench compares upper-cased text. Preflight also accepts the same number written differently. */
export function compareCvar(rule: string, value: string): 'same' | 'format' | 'different' {
  if (value.toUpperCase() === rule) return 'same';
  return Numeric.test(rule) && Numeric.test(value) && Number(rule) === Number(value) ? 'format' : 'different';
}

/** The number in "<name>_<number>.dem", and the name, or undefined. */
export function demoNumber(file: string): { prefix: string; n: number } | undefined {
  const m = /^(.*)_(\d+)\.dem$/i.exec(file.split(/[\\/]/).pop()!);
  return m ? { prefix: m[1], n: Number(m[2]) } : undefined;
}

/** "1:02:03.456", "2:03.456" or "0:03.456". */
export function clock(s: number, digits = 3) {
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), rest = (s % 60).toFixed(digits).padStart(digits + 3, '0');
  return h ? `${h}:${String(m).padStart(2, '0')}:${rest}` : `${m}:${rest}`;
}

export const formatTime = (t: Time) => clock(seconds(t));

export function checkRun(inputs: Input[], options: { mode?: Mode } = {}): Report {
  // Run order: by demo number, then name (VolvoWrench sorts by number only).
  const order = (i: Input) => demoNumber(i.name)?.n ?? -Infinity;
  const files = [...inputs].sort((a, b) => order(a) - order(b) || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));

  const findings = new Map<string, Finding>();
  const add = (kind: Kind, subject: string, where: Where) => {
    const key = `${kind}\n${subject}`;
    const f = findings.get(key);
    if (f) f.where.push(where);
    else findings.set(key, { kind, severity: Kinds[kind].severity, subject, where: [where] });
  };

  const detectedMode = detectMode(files[0]?.demo);
  const mode = options.mode ?? detectedMode;
  const saves = new Set<string>(); // Saves made so far in the run.
  let blueShiftStart: Time | undefined;
  let time: Time | undefined;
  let gameEnded = false, timerStarted = false, timerMoved = false;
  const demos: Report['demos'] = [];
  const timeline: { name: string; first: Time; last: Time; recovered?: boolean }[] = [];

  for (const { name, demo } of files) {
    const where = (at?: At): Where => ({ demo: name, ...at });
    if (demo.error) add(demo.recovered ? 'unfinished' : 'broken', demo.recovered ? '' : demo.error, where());

    const { mapName: map, gameDir } = demo.header;
    for (const { vars, ...at } of demo.moveVars)
      for (const [k, normal] of Object.entries(rules.physics))
        if (vars[k as keyof typeof vars] !== normal) add('physics', `${k} ${+vars[k as keyof typeof vars].toPrecision(7)} (must be ${normal})`, where(at));

    const cvarRules = new Map(Object.entries(rules.cvars));
    if (mode === 'scriptless') for (const [k, v] of Object.entries(rules.scriptlessCvars)) cvarRules.set(k, v);
    if (rules.skillGameDirs.some(d => gameDir.startsWith(d))) {
      const skill = { ...rules.skillCvars, ...(map.startsWith('ba_') ? rules.blueShiftSkillCvars : {}) };
      for (const [k, v] of Object.entries(skill)) cvarRules.set(k, v);
    }

    let hasBxt = false, gameEnd = false, firstTime: Time | undefined, demoTime: Time | undefined;
    for (const group of demo.bxt) {
      const at = where({ frame: group.frame, time: group.time });
      const groupTime = group.data.find(d => d.type === 'time');
      // Key presses in this frame, to tell a pressed jump or duck from a scripted one.
      const presses = { '+JUMP': 0, '-JUMP': 0, '+DUCK': 0, '-DUCK': 0 };

      for (const d of group.data) {
        switch (d.type) {
          case 'version':
            hasBxt = true;
            if (d.version !== rules.bxtVersion) add('bxt-version', d.version, at);
            break;
          case 'cvars':
            if (d.values.has(rules.steamCvar)) {
              for (const [k, v] of Object.entries(rules.steamCvars)) cvarRules.set(k, v);
              for (const k of rules.steamRemoves) cvarRules.delete(k);
            }
            for (const [k, v] of d.values) {
              const rule = cvarRules.get(k.toUpperCase());
              if (rule === undefined) continue;
              const same = compareCvar(rule, v);
              if (same !== 'same' && ThirdPerson.includes(k.toLowerCase())) add('third-person', `${k.toLowerCase()} "${v}"`, at);
              else if (same !== 'same') add(same === 'format' ? 'cvar-format' : 'cvar', `${k.toLowerCase()} "${v}" (must be ${rule ? `"${rule.toLowerCase()}"` : 'empty'})`, at);
            }
            break;
          case 'time':
            firstTime ??= d;
            demoTime = d;
            timerMoved ||= seconds(d) > MaxTimerJump;
            break;
          case 'bind': {
            const moves = pressesMovement(d.command);
            if (moves) add('movement-script', d.command.trim(), at);
            if (mode !== 'scriptless') break;
            const cmd = d.command.trim().toUpperCase();
            for (const p of Object.keys(presses) as (keyof typeof presses)[]) if (cmd.includes(p)) presses[p]++;
            if (cmd.includes(';') && !moves) add('bind-script', d.command.trim(), at);
            if (cmd.includes('REPORT_TO_DEMO')) add('report-to-demo', d.command.trim(), at);
            break;
          }
          case 'alias': {
            const cmd = d.command.trim();
            if (pressesMovement(cmd)) {
              add('movement-script', `${d.name}: ${cmd}`, at);
              break;
            }
            if (mode === 'scriptless' && cmd.includes(';')) add('alias-script', `${d.name}: ${cmd}`, at);
            if (mode === 'scripted' && Movement.some(m => cmd.toUpperCase().includes(m))) add('alias-movement', `${d.name}: ${cmd}`, at);
            break;
          }
          case 'script':
            add('config', d.filename, at);
            break;
          case 'command':
            checkCommand(d.command.trim(), mode, presses, saves, cvarRules, timerMoved, add, at);
            if (/^bxt_timer_start\b/i.test(d.command.trim())) timerStarted = true;
            if (!blueShiftStart && d.command.trim().toLowerCase() === BlueShiftStart && groupTime?.type === 'time') blueShiftStart = groupTime;
            break;
          case 'gameEnd':
            if (gameEnd) break;
            gameEnd = true;
            add('game-end', map, at);
            if (map.startsWith('ba_') && groupTime?.type === 'time') {
              const start = blueShiftStart ?? { hours: 0, minutes: 0, seconds: 0, remainder: 0 };
              const s = seconds(groupTime) - seconds(start);
              add('blue-shift', `${formatTime(fromSeconds(s))} (${formatTime(groupTime)} minus ${formatTime(start)})`, at);
            }
            break;
          case 'trigger':
            add('trigger', `${d.command} at (${d.min.join(', ')}) to (${d.max.join(', ')})`, at);
            break;
          case 'split':
            add('split', `${d.name || '(unnamed)'} on ${d.map} at (${d.min.join(', ')}) to (${d.max.join(', ')})`, at);
            break;
          case 'edicts':
            if (d.edicts > 900) add('edicts', String(d.edicts), at);
            break;
          case 'flags':
            if (d.flags & 1) add('big-map', 'bxt_enable_big_map', at);
            break;
        }
      }
    }
    if (!hasBxt && !(demo.error && !demo.recovered)) add('no-bxt', '', where());
    if (demoTime) time = demoTime;
    if (firstTime && demoTime) timeline.push({ name, first: firstTime, last: demoTime, recovered: demo.recovered });
    gameEnded ||= gameEnd;
    demos.push({ name, map, ...(demoTime && { time: demoTime }), ...(demo.error && { error: demo.error }) });
  }

  // Individual levels start away from the first map with the timer at zero (some, like Hazard Course, end the game),
  // or start the timer inside a demo and don't end the game.
  const [start] = timeline;
  const first = files[0]?.demo.header;
  const offStart = !!first?.gameDir.startsWith('valve') && first.mapName !== StartMap && !!start && seconds(start.first) <= MaxTimerJump;
  const individualLevel = offStart || (timerStarted && !gameEnded);
  checkDemoSet(files, add, individualLevel);
  if (start && seconds(start.first) > MaxTimerJump && !individualLevel)
    add('timer-start', `${formatTime(start.first)} at the start of ${start.name}`, { demo: start.name });
  for (const [i, b] of timeline.entries()) {
    const a = timeline[i - 1];
    if (!a) continue;
    // An unfinished demo's last time is only known to the second.
    const gap = seconds(b.first) - seconds(a.last);
    if (gap > MaxTimerJump + (a.recovered ? 1 : 0) || gap < -0.01)
      add('timer-jump', `${formatTime(a.last)} at the end of ${a.name}, then ${formatTime(b.first)} at the start of ${b.name}`, { demo: b.name });
  }
  // With demos missing, a save that was never made may simply be in one of them.
  if (['missing', 'timer-start', 'timer-jump'].some(k => [...findings.keys()].some(key => key.startsWith(`${k}\n`))))
    for (const [key, f] of findings) if (f.kind === 'load-unknown') findings.set(key, { ...f, kind: 'load-unseen' });
  if (timeline.length && !gameEnded && !individualLevel) add('no-game-end', '', { demo: timeline[timeline.length - 1].name });

  const severityOrder = { problem: 0, check: 1, info: 2 };
  const kindOrder = Object.keys(Kinds);
  const ok = files.filter(f => f.demo.stats.count > 0).map(f => f.demo.stats);
  return {
    mode,
    detectedMode,
    demos,
    ...(time && { time }),
    findings: [...findings.values()].sort((a, b) => severityOrder[a.severity] - severityOrder[b.severity] || kindOrder.indexOf(a.kind) - kindOrder.indexOf(b.kind)),
    fps: {
      highest: ok.length ? 1 / Math.min(...ok.map(s => s.frametimeMin)) : 0,
    },
    individualLevel,
    rules: { bxtVersion: rules.bxtVersion, source: rules.source },
  };
}

function checkCommand(
  command: string, mode: Mode, presses: Record<'+JUMP' | '-JUMP' | '+DUCK' | '-DUCK', number>, saves: Set<string>,
  cvarRules: Map<string, string>, timerMoved: boolean, add: (kind: Kind, subject: string, where: Where) => void, at: Where,
) {
  const cmd = command.toUpperCase();
  if (cmd.startsWith('BIND') || cmd.startsWith('ALIAS')) return; // Making binds and aliases is fine; using them is checked.

  // Setting a cvar to its required value, or reading it, changes nothing. VolvoWrench flags these anyway.
  const [name, value] = command.split(/\s+/);
  const rule = cvarRules.get(name.toUpperCase());
  if (rule !== undefined && (value === undefined || compareCvar(rule, value.replace(/^"(.*)"$/, '$1')) !== 'different')) return;
  // The run-start bind may start or reset the timer, before it has moved.
  if (!timerMoved && /^bxt_timer_(start|reset)$/i.test(name)) return;
  if (ThirdPerson.includes(name.toLowerCase())) return add('third-person', command, at);

  if (mode === 'scriptless') {
    for (const p of ['+JUMP', '-JUMP', '+DUCK', '-DUCK'] as const) {
      if (!cmd.includes(p)) continue;
      if (presses[p] === 0) add(p.endsWith('JUMP') ? 'autojump' : 'ducktap', command, at);
      else presses[p]--;
    }
  }
  if (cmd.includes('BXT')) {
    const allowed = mode === 'scriptless' ? rules.allowedBxtCommands : [...rules.allowedBxtCommands, ...rules.scriptedBxtCommands];
    if (!allowed.some(a => cmd.includes(a))) add('bxt-command', command, at);
  }
  // The engine adds ".sav" itself, so "load x" and "load x.sav" are the same save. VolvoWrench compares the text.
  const saveName = (s: string) => s.trim().replace(/\.SAV$/, '');
  if (cmd.startsWith('SAVE')) saves.add(saveName(cmd.slice(4)));
  else if (command === 'autosave') saves.add('AUTOSAVE');
  if (cmd.startsWith('LOAD')) {
    const save = saveName(cmd.slice(4));
    if (!saves.has(save)) add('load-unknown', command, at);
    else add(AlwaysLoadable.includes(save) ? 'load' : 'load-named', command, at);
  }
  if (cmd.includes('CUST_') && !rules.allowedCust.some(c => cmd.includes(c))) add('cust', command, at);
  if (disallowed(cmd, mode)) add('disallowed', command, at);
  if (probablyDisallowed(cmd, mode)) add('probably-disallowed', command, at);
}

function checkDemoSet(files: Input[], add: (kind: Kind, subject: string, where: Where) => void, individualLevel: boolean) {
  const numbered = files.map(f => ({ f, id: demoNumber(f.name) }));
  const prefixes = new Set(numbered.flatMap(x => (x.id ? [x.id.prefix.toLowerCase()] : [])));
  for (const { f, id } of numbered) if (!id) add('naming', f.name, { demo: f.name });
  if (prefixes.size > 1) for (const { f, id } of numbered) if (id) add('naming', `${f.name} (the demos have ${prefixes.size} different names)`, { demo: f.name });

  const byNumber = new Map<number, Input[]>();
  for (const { f, id } of numbered) if (id) byNumber.set(id.n, [...(byNumber.get(id.n) ?? []), f]);
  for (const same of byNumber.values()) {
    for (const f of same.slice(1)) {
      const copy = f.hash !== undefined && f.hash === same[0].hash;
      add(copy ? 'copy' : 'conflict', `${same[0].name} and ${f.name}`, { demo: f.name });
    }
  }
  // Gaps as ranges. A full run's demos start at 1; an individual level's numbering may start anywhere.
  const numbers = [...byNumber.keys()];
  const last = Math.max(0, ...numbers);
  const prefix = numbered.find(x => x.id)?.id?.prefix;
  for (let n = individualLevel ? Math.min(...numbers) : 1; n < last; n++) {
    if (byNumber.has(n)) continue;
    let end = n;
    while (end + 1 < last && !byNumber.has(end + 1)) end++;
    const first = `${prefix}_${n}.dem`;
    add('missing', end === n ? first : `${first} to ${prefix}_${end}.dem (${end - n + 1} demos)`, { demo: first });
    n = end;
  }
}

function fromSeconds(s: number): Time {
  const whole = Math.floor(s);
  return { hours: Math.floor(whole / 3600), minutes: Math.floor((whole % 3600) / 60), seconds: whole % 60, remainder: s - whole };
}
